<template>
  <div v-if="!isEditing" class="phone-number">
    <span v-if="!customer.phone" class="phone-number__text no-number">
      {{ getTranslatedText('loyaltyProgramConfig.stepper.step2.noPhone') }}
    </span>
    <span v-else class="phone-number__text incorrect-number">
      {{ customer.phone }}
    </span>
    <v-btn color="primary" icon class="ml-2" @click="editPhoneNumber">
      <v-icon>mdi-pencil</v-icon>
    </v-btn>
  </div>
  <div v-else class="phone-number">
    <v-text-field
      v-model="inputs.phone"
      :ref="`phone-number-${customer.id}`"
      type="number"
      class="custom-text-field"
      hide-details
      filled
      rounded
      dense
      autofocus
      @input="$v.inputs.phone.$touch()"
    />
    <v-btn
      color="primary"
      icon
      class="ml-2"
      ref="saveButton"
      :disabled="$v.inputs.$error"
      @click="savePhoneNumber"
    >
      <v-icon>mdi-content-save</v-icon>
    </v-btn>
  </div>
</template>

<script>
import { integer, required } from 'vuelidate/lib/validators'

import CUSTOMERS_DB_API_EVENTS from '@/config/events/databaseAPI/customersEvents'

import { getTranslatedText } from '@/tools/data'

import { validatePhoneNumber } from '@/tools/customValidations'

import rendererEventsService from '@/services/renderer/rendererEvents'

export default {
  name: 'InputPhone',
  props: {
    customer: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      isEditing: false,
      inputs: {},
      validators: { inputs: {} },
    }
  },
  validations() {
    return this.validators
  },
  methods: {
    getTranslatedText,
    setInputs() {
      this.$set(this.inputs, 'phone', this.customer.phone)
      this.$set(this.validators.inputs, 'phone', {
        required,
        integer,
        validatePhoneNumber,
      })
    },
    editPhoneNumber() {
      this.setInputs()
      this.$v.inputs.phone.$touch()
      this.isEditing = true
    },
    savePhoneNumber() {
      if (this.$v.inputs.$error) return
      rendererEventsService.send(CUSTOMERS_DB_API_EVENTS.channel, {
        event: CUSTOMERS_DB_API_EVENTS.events.updateById.name,
        data: {
          id: this.customer.id,
          data: { mobile_number: this.inputs.phone },
        },
      })
      this.isEditing = false
    },
  },
}
</script>

<style scoped lang="scss">
.phone-number {
  display: flex;
  flex-direction: row;
  justify-content: flex-start;
  align-items: center;
  &__text {
    color: var(--v-accentLight-darken2);
    flex-basis: 150px;
    &.incorrect-number {
      text-decoration: var(--v-error-base) wavy underline;
    }
  }
  .custom-text-field {
    max-width: 150px;
    :deep(.v-input__slot) {
      padding: 0 10px;
      min-height: 35px;
    }
    :deep(input) {
      &::-webkit-outer-spin-button,
      &::-webkit-inner-spin-button {
        -webkit-appearance: none;
        margin: 0;
      }
      &[type='number'] {
        -moz-appearance: textfield;
      }
    }
  }
}
</style>
