<template>
  <v-data-table
    id="data-table-selection-container"
    ref="customerSelectionTable"
    class="d-flex flex-column paginated-table"
    show-select
    multi-select
    hide-default-footer
    checkbox-color="primary"
    :headers="config.headers"
    :items="config.state.items"
    :selected-items="config.state.selectedItems"
    :item-key="config.itemKey"
    :loading="config.state.fetching"
    :sort-by="config.sortBy"
    :sort-desc="config.sortDesc"
    :items-per-page.sync="rowsPerPage"
    :page.sync="page"
    @input="updateSelectedItems"
    v-model="selected"
  >
    <!-- Loader -->
    <template slot="loading">
      <v-overlay
        :value="config.state.fetching"
        absolute
        class="paginated-table__fetching"
        opacity="0.15"
      >
        <SyncLoader :color="loaderColor" />
      </v-overlay>
    </template>
    <!-- Table top -->
    <template v-slot:top>
      <div id="data-table-header-custom">
        <slot name="top">
          <div class="d-flex justify-space-between paginated-table__header">
            <div class="d-flex align-center pb-6">
              <v-icon color="primary" large>{{ config.icon }}</v-icon>
              <FormattedText
                intl
                type="title"
                color="textPrimary"
                :value="config.title"
                :class="config.titleClass ? config.titleClass : ''"
              />
            </div>
          </div>
        </slot>
      </div>
    </template>
    <!-- Select all checkbox -->
    <template v-slot:[`header.data-table-select`]>
      <v-simple-checkbox
        color="primary"
        :value="allItemsSelected"
        @click="toggleSelectAll"
        :indeterminate="selected.length > 0 && !allItemsSelected"
      />
    </template>
    <!-- item row -->
    <template
      v-for="column in config.headers"
      v-slot:[`item.${column.value}`]="{ item }"
    >
      <span :key="column.value">{{ getNestedValue(item, column) }}</span>
    </template>
    <!-- slot column -->
    <template
      v-for="column in config.slotColumns"
      v-slot:[`item.${column}`]="{ item }"
    >
      <slot :name="column" :item="item" />
    </template>
    <!-- showChipComponent -->
    <template
      v-slot:[`item.${config.showChipComponent.itemKey}`]="{ item }"
      v-if="config.showChipComponent"
    >
      <v-chip :color="getChipColor(item)" text-color="white">
        {{ getValue(item) }}
      </v-chip>
    </template>
    <!-- actions -->
    <template v-slot:[`item.actions`]="{ item }">
      <slot name="actions" :item="item" />
    </template>
    <!-- Table footer -->
    <template v-slot:footer>
      <v-row
        class="no-gutters mt-auto py-2 shrink"
        align="center"
        justify="end"
      >
        <div v-if="config.state.items.length > 0">
          <v-spacer />
          <span class="mr-4 grey--text">
            {{ getTranslatedText('dataIterator.pageText', page) }}
            <span
              v-text="numberOfPages"
              class="font-weight-bold primary--text"
            />
          </span>
          <v-btn
            small
            dark
            rounded
            color="primary"
            class="mr-1"
            @click="formerPage"
          >
            <v-icon>mdi-chevron-left</v-icon>
          </v-btn>
          <v-btn
            small
            dark
            rounded
            color="primary"
            class="ml-1"
            @click="nextPage"
          >
            <v-icon>mdi-chevron-right</v-icon>
          </v-btn>
        </div>
      </v-row>
    </template>
  </v-data-table>
</template>

<script>
import { SyncLoader } from '@saeris/vue-spinners'

import { getTranslatedText } from '@/tools/data'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'PaginatedTableSelection',
  components: {
    SyncLoader,
    FormattedText,
  },
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      selected: [],
      rowsPerPage: this.config.rowsPerPage,
      page: this.config.page,
    }
  },
  computed: {
    loaderColor() {
      const { light, dark } = this.config.loaderColor
      return this.$vuetify.theme.dark ? dark : light
    },
    numberOfPages() {
      return Math.ceil(this.config.state.items.length / this.rowsPerPage)
    },
    allItemsSelected() {
      return this.selected.length === this.config.state.items.length
    },
  },
  methods: {
    getTranslatedText,
    selectAllItems() {
      this.selected = [...this.config.state.items]
      this.$emit('updateSelectedItems', this.selected)
    },
    deselectAllItems() {
      this.selected = []
      this.$emit('updateSelectedItems', this.selected)
    },
    toggleSelectAll() {
      this.allItemsSelected ? this.deselectAllItems() : this.selectAllItems()
    },
    getRowsPerPage() {
      const container = document.getElementById(
        'data-table-selection-container'
      )
      const tableTopHeight = document.getElementById('data-table-header-custom')
        .offsetHeight
      const minItemHeight = this.config.rowOffsetHeight
      const containerHeight = parseInt(container.offsetHeight, 0)
      this.rowsPerPage = Math.floor(
        Math.max(
          containerHeight - minItemHeight - tableTopHeight,
          minItemHeight
        ) / minItemHeight
      )
    },
    formerPage() {
      if (this.page - 1 >= 1) this.page -= 1
    },
    nextPage() {
      if (this.page + 1 <= this.numberOfPages) this.page += 1
    },
    updateSelectedItems(selectedItems) {
      this.selected = selectedItems
      this.$emit('updateSelectedItems', selectedItems)
    },
    getChipColor(item) {
      return typeof this.config.showChipComponent.color === 'function'
        ? this.config.showChipComponent.color(item)
        : this.config.showChipComponent.color
    },
    getValue(item) {
      return typeof this.config.showChipComponent.value === 'function'
        ? this.config.showChipComponent.value(item)
        : this.config.showChipComponent.value
    },
    getNestedValue(item, column) {
      const properties = column.value.split('.')
      let value = item
      for (const prop of properties) {
        value = value?.[prop]
        if (value === undefined || value === null) {
          break
        }
      }
      return column.format(value)
    },
  },
  watch: {
    'config.state.windowHeight': function(newValue, oldValue) {
      if (oldValue !== newValue) {
        this.getRowsPerPage()
      }
    },
    'config.state.selectedItems': function(value) {
      this.selected = [...value]
    },
  },
  mounted() {
    // Wait container render finish
    setTimeout(() => {
      this.getRowsPerPage()
    }, 300)
  },
}
</script>

<style lang="scss" scoped>
.paginated-table {
  background-color: var(--v-mainBackground-base) !important;
  height: 100%;
  overflow: hidden;
  .paginated-table__fetching {
    height: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-direction: column;
  }
  .paginated-table__header {
    height: 90px;
  }
}

#data-iterator-container {
  align-content: flex-start;
}
.fade-enter, .fade-leave-to /* .fade-leave-active below version 2.1.8 */ {
  opacity: 0;
}

.slide-in-enter {
  opacity: 0;
  transform: scale(0.8);
}
.slide-in-enter-active {
  transition: all 0.4s ease;
}

.custom-checkbox {
  padding-top: 0;
  margin-top: 0;
}
</style>
